INSERT INTO squad_entries VALUES(10,1,11,NULL,'FB','OWNED','0001101128000370014X00144',6.459999999999999965,'season','RB 8선발 704분 평균 6.46 · 피크 7.1 (RDM 6.84보다 낮음 — 난도 미보정)','fb_wingback','Balanced',0.8319999999999999619,'appearances measured (2026-07-21 슬롯 추가)','OWNED — 표본 n=1 긴급배치 / 🔄 **[2026-07-31 obs#104]** 그리드를 **1경기 → 8선발 전수 집계**로 교체(557 히트포인트, `player_match_grids` 8행 신규 적재). 옛 값은 긴급 출전 1경기 표본이었고 정의 없는 밴드 `r1`을 쓰고 있었다. ⚠️ **자기진영 질량이 1.2 → 2.4로 배가**됐다 — 1경기 표본이 그의 전진 성향을 과대평가하고 있었다. 적합: att_wb/Support .890→.854 · wingback/Support .808→.795 · wingback/Balanced .761→**.832**. 처방을 같은 역할 안에서 Support → **Balanced**로 옮겼다(전방 질량 둘 다 0.30이라 C2 불변, 뱅크는 1.2→1.6으로 rest-defense 성격에 더 부합). 옛↔신 그리드 코사인 .904.',22,NULL,NULL);
