INSERT INTO squad_entries VALUES(18,1,60,'아브라함(보유)','ST','OWNED','239324777256X732212211410',6.950000000000000177,'r6','확장 25경기 평균 6.95','st_false9','Attack',0.6430000000000000159,'appearances measured','OWNED',71,'Beşiktaş 임대 (사실상 전량)','⚠️ **분리 시도 결과(2026-08-12): 빌라분이 4경기뿐이라 분리 불가.** 25경기 중 21경기가 베식타스 임대분(수페르리그·컨퍼런스, 2025-08~2026-01)이고 빌라 복귀분은 4경기(PL 2·EL 1·FA 1)다. 혼합 그리드(st_false9/Attack .643)는 베식타스 단독 그리드(.652)와 사실상 같다 — 즉 이 그리드는 베식타스 기록으로 읽어야 한다. 빌라 4경기만 재면 .541이나 표본 미달(§3 기준 6경기)이라 채택하지 않는다.');
